mapper.sql:
WHERE active AND tier IN ('CORE', 'BROAD')
 AND tier = #{tier}
 AND journal_type = #{journalType}
 AND publication_status = #{publicationStatus}
 AND title ILIKE '%' || #{q} || '%'

mapper.update:
UPDATE source SET is_oa = COALESCE(#{isOa}, is_oa), in_doaj = COALESCE(#{inDoaj}, in_doaj), modified = now()
WHERE id = #{id}
  AND (is_oa, in_doaj) IS DISTINCT FROM (COALESCE(#{isOa}, is_oa), COALESCE(#{inDoaj}, in_doaj))

mapper.select:
SELECT s.* FROM source s ORDER BY
s.candidate_score DESC NULLS LAST, s.id lower(s.title), s.id s.id
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE source SET dormant_since = #{since}, dormant_evidence = #{evidence, jdbcType=VARCHAR}::jsonb
WHERE id = #{id}
  AND (dormant_since, dormant_evidence) IS DISTINCT FROM (#{since}::date, #{evidence, jdbcType=VARCHAR}::jsonb)
